        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Kardeşleri demişlerdi ki: \"Yusuf ve özkardeşi babamıza bizden daha sevgilidir. Oysa biz bir cemaatiz. Babamız açık bir yanlışlık içindedir"
        }
