      "ar": "فَلَمَّا رَجَعُواْ إِلَىٰ أَبِيهِمْ قَالُواْ يَـٰأَبَانَا مُنِعَ مِنَّا الْكَيْلُ فَأَرْسِلْ مَعَنَا أَخَانَا نَكْتَلْ وَإِنَّا لَهُ لَحَٰفِظُونَ",
      "translit": "Falammā rajaʿū ilā abīhim qālū yāʾabānā muniʿa minnā l-kaylu faʾarsil maʿanā akhānā naktal waʾinnā lahū laḥāfiẓūn",
